47	
48	/// The checker binaries a `tsc_path` may name, the builds whose protocol this backend was traced against (the built-in
49	/// checker is pinned in `Cargo.toml` instead): the `typescript` 7.1 series, from `7.1.0-beta` on, and the `tsrs` builds
50	/// listed exactly (`<tsrs version>-ts<typescript version>`), each only while its TypeScript part is in the series above.
51	/// The protocol has no version handshake, so the package's `package.json` version and the initialize call that follows
52	/// the spawn are the whole check; a build that fails either takes the structural result with one warning.
53	pub const SUPPORTED_VERSIONS: &[&str] = &["7.1", "0.23.0-ts7.1.0-beta"];
54	
55	/// How many files are asked about at once, shared among the programs. A program's checker answers requests one at a
56	/// time; this keeps it from idling between them.
57	const FILES_IN_FLIGHT: usize = 16;
58	
59	/// The most threads the whole-project run converts the checker's answers on: past four, the checker's own thread is
60	/// the bound (measured on Chakra's components, docs/gate-measurements.md).
61	const CONVERTER_THREADS: usize = 4;
62	
63	/// How many programs a whole-project run asks at once, each on a thread of the linked checker: a program's requests are
64	/// answered one at a time, and the checker's answering is what bounds the run (docs/gate-measurements.md).
65	const CHECKER_PROGRAMS: usize = 2;
66	
67	/// The fewest files a program answers for: a project smaller than this asks one program, which builds no second checker
68	/// for a handful of components.
69	const MIN_FILES_PER_PROGRAM: usize = 32;
70	
71	/// A component the structural pass found.
72	pub use caliper_docgen_core::types::semantic::SemanticTarget as Target;
73	
74	/// The components of `output`, in output order.
75	pub fn targets_of(output: &ExtractionOutput) -> Vec<Target> {
76	    output
77	        .components
78	        .iter()
79	        .map(|(key, entry)| Target {
80	            key: key.clone(),
81	            file_path: entry.file_path.clone(),
82	            display_name: entry.display_name.clone(),
83	            exports: entry.exports.clone(),
84	            described: entry
85	                .props
86	                .values()
87	                .filter(|prop| !prop.description.is_empty())
88	                .map(|prop| prop.name.clone())
89	                .collect(),
90	            // The whole-project merge leaves `@types/react`'s props to the inheritance layers.
91	            react_wanted: Some(Default::default()),
92	        })
93	        .collect()
94	}
95	
96	/// One whole-project request to the checker: the components to answer for, and which checker to ask. Built with
97	/// [`SemanticRequest::new`] and answered by [`resolve`].
98	#[derive(Debug, Clone)]
99	pub struct SemanticRequest {
100	    /// Where the checker finds `node_modules`: its working directory.
101	    pub project_root: Utf8PathBuf,
102	    /// A tsconfig whose compiler options the checker uses (read with `parseConfigFile`); with none, a default set.
103	    pub tsconfig: Option<Utf8PathBuf>,
104	    /// A checker binary to run as a `tsc --api` process (`typescript@7.1`'s `tsc`, or `tsrs`) instead of the built-in
105	    /// checker.
106	    pub tsc_path: Option<Utf8PathBuf>,
107	    /// The components to ask about.
108	    pub targets: Vec<Target>,
109	    /// Bound on each request, and on a checker process's start-up handshake.
110	    pub request_timeout: Duration,
111	    /// The versions a checker binary's `package.json` may declare; one that is not among them is a start-up failure.
112	    /// The built-in checker is pinned and not checked.
113	    pub expected_versions: &'static [&'static str],
114	    /// Write every request and its answer here as JSON, to refresh the replay fixture the tests use.
115	    pub record_to: Option<Utf8PathBuf>,
116	    /// Environment for a checker process; the tests use it to pick a replay scenario.
117	    pub extra_env: Vec<(String, String)>,
118	    /// Ask the checker about a component's props, and about the members of each type, last to first. The answer must
119	    /// not change: no id the checker hands out, and so no order of queries, may show in it. The tests set this.
120	    pub reverse_queries: bool,
121	}
122	
123	impl SemanticRequest {
124	    /// A request for `targets` under `project_root`, with a 60 second timeout, the supported versions, and no
125	    /// tsconfig or explicit `tsc` path.
126	    pub fn new(project_root: Utf8PathBuf, targets: Vec<Target>) -> Self {
127	        Self {
128	            project_root,
129	            tsconfig: None,
130	            tsc_path: None,
131	            targets,
132	            request_timeout: Duration::from_secs(60),
133	            expected_versions: SUPPORTED_VERSIONS,
134	            record_to: None,
135	            extra_env: Vec::new(),
136	            reverse_queries: false,
137	        }
138	    }
139	}
140	
141	/// Resolves the request's components with the checker. Blocks; builds its own runtime, so it must not be called from
142	/// inside one. The runtime has up to four threads: the built-in checker answers two programs at once, each on a thread
143	/// of its own, and while it does, the answers it gave the other files in flight are read and converted on these.
144	pub fn resolve(request: SemanticRequest) -> SemanticOutcome {
145	    let threads = std::thread::available_parallelism().map_or(1, |count| count.get().min(CONVERTER_THREADS));
146	    let built = tokio::runtime::Builder::new_multi_thread().worker_threads(threads).enable_all().build();
147	    let runtime = match built {
148	        Ok(runtime) => runtime,
149	        Err(error) => return SemanticOutcome::unavailable(format!("could not start an async runtime: {error}")),
150	    };
151	    runtime.block_on(run(request, None))
152	}
153	
154	/// The exported targets by file, in first-seen order, and an outcome that already holds a fallback for each target
155	/// the checker cannot be asked about.
156	fn group_by_file(request: &SemanticRequest) -> (SemanticOutcome, FxHashMap<&Utf8Path, Vec<&Target>>, Vec<&Utf8Path>) {
157	    let mut outcome = SemanticOutcome::default();
158	    let mut by_file: FxHashMap<&Utf8Path, Vec<&Target>> = FxHashMap::default();
159	    let mut order: Vec<&Utf8Path> = Vec::new();
160	    for target in &request.targets {
161	        if target.exports.is_empty() {
162	            outcome.fallbacks.push(fallback_of(target, "not exported by its module"));
163	            continue;
164	        }
165	        let group = by_file.entry(target.file_path.as_path()).or_default();
166	        if group.is_empty() {
167	            order.push(target.file_path.as_path());
168	        }
169	        group.push(target);
170	    }
171	    (outcome, by_file, order)
172	}
173	
174	/// The checker `request` names: its `tsc_path` as a process, else the built-in one.
175	async fn start_checker(request: &SemanticRequest, threads: usize) -> Result<Backend, String> {
176	    Backend::start(Start {
177	        project_root: &request.project_root,
178	        tsc_path: request.tsc_path.as_deref(),
179	        expected_versions: request.expected_versions,
180	        timeout: request.request_timeout,
181	        extra_env: &request.extra_env,
182	        threads,
183	    })
184	    .await
185	}
186	
187	/// Answers `request` with a checker started for it, asking `programs` programs at once, or by default as many as
188	/// [`CHECKER_PROGRAMS`] and the files allow ([`MIN_FILES_PER_PROGRAM`]).
189	async fn run(request: SemanticRequest, programs: Option<usize>) -> SemanticOutcome {
190	    if request.targets.iter().all(|target| target.exports.is_empty()) {
191	        return group_by_file(&request).0;
192	    }
193	    let files = group_by_file(&request).2.len();
194	    let programs = programs.unwrap_or_else(|| CHECKER_PROGRAMS.min(files.div_ceil(MIN_FILES_PER_PROGRAM))).max(1);
195	    let checker = match start_checker(&request, programs).await {
196	        Ok(checker) => checker,
197	        Err(reason) => return SemanticOutcome::unavailable(reason),
198	    };
199	    let outcome = answer_with(&checker, &request).await;
200	    checker.shutdown().await;
201	    outcome
202	}
203	
204	/// The files of the request's exported targets, in first-seen order: the roots of the program that answers it.
205	fn root_files(request: &SemanticRequest) -> Vec<String> {
206	    group_by_file(request).2.iter().map(|file| file.to_string()).collect()
207	}
208	
209	/// Answers the request's targets with a checker that is already running: one snapshot of as many programs rooted at
210	/// their files as the checker answers at once ([`Backend::parallel_programs`]), released once they are answered.
211	async fn answer_with(checker: &Backend, request: &SemanticRequest) -> SemanticOutcome {
212	    let files = root_files(request);
213	    if files.is_empty() {
214	        return group_by_file(request).0;
215	    }
216	    let started = std::time::Instant::now();
217	    let tsconfig = request.tsconfig.as_ref().map(|path| path.as_str());
218	    let count = checker.parallel_programs();
219	    let record = request.record_to.is_some();
220	    let opened = Rpc::open_programs(checker.client(), request.request_timeout, tsconfig, &files, record, count).await;
221	    let programs: Vec<Arc<Rpc>> = match opened {
222	        Ok(programs) => programs.into_iter().map(Arc::new).collect(),
223	        Err(error) => return SemanticOutcome::unavailable(format!("the checker stopped answering: {error}")),
224	    };
225	    tracing::debug!(program_ms = started.elapsed().as_millis() as u64, programs = count, "semantic program built");
226	    let answered = answer_on(&programs, request, &files).await;
227	    if let Some(first) = programs.first() {
228	        first.release().await;
229	    }
230	    answered.unwrap_or_else(|error| SemanticOutcome::unavailable(format!("the checker stopped answering: {error}")))
231	}
232	
233	/// Answers the request's targets on a snapshot whose programs are each rooted at `files` ([`root_files`]), one session
234	/// bound to each: a file is answered by one of them, the `n`th file by the `n % programs.len()`th. Each program has its
235	/// checker and its handles, so each has its own [`Converter`]; since every program holds the same files, each answers
236	/// a component as any other would, and the output does not depend on how the files are shared out. The snapshot is
237	/// left as it is, for the caller to keep or release.
238	async fn answer_on(
239	    programs: &[Arc<Rpc>],
240	    request: &SemanticRequest,
241	    files: &[String],
242	) -> Result<SemanticOutcome, CallError> {
243	    let (mut outcome, by_file, order) = group_by_file(request);
244	    let mut answered = session(programs, request, files, &by_file, &order).await?;
245	    outcome.components.append(&mut answered.components);
246	    outcome.fallbacks.append(&mut answered.fallbacks);
247	    Ok(outcome)
248	}
249	
250	async fn session(
251	    programs: &[Arc<Rpc>],
252	    request: &SemanticRequest,
253	    files: &[String],
254	    by_file: &FxHashMap<&Utf8Path, Vec<&Target>>,
255	    order: &[&Utf8Path],
256	) -> Result<SemanticOutcome, CallError> {
257	    let started = std::time::Instant::now();
258	    let Some(rpc) = programs.first() else { return Ok(SemanticOutcome::default()) };
259	    let converters: Vec<Converter> =
260	        programs.iter().map(|program| Converter::new(program.clone(), request.reverse_queries)).collect();
261	    let interner = Arc::new(PropInterner::default());
262	    // The files in order; each worker takes the next one when it is done with its last, so a program whose files take
263	    // longer answers fewer of them.
264	    let queue: VecDeque<Vec<Target>> = order
265	        .iter()
266	        .map(|file| by_file.get(file).into_iter().flatten().map(|target| (*target).clone()).collect())
267	        .collect();
268	    let queue = Arc::new(Mutex::new(queue));
269	
270	    let mut tasks = JoinSet::new();
271	    for worker in 0..FILES_IN_FLIGHT {
272	        let lane = worker % programs.len();
273	        let (Some(rpc), Some(converter)) = (programs.get(lane), converters.get(lane)) else { continue };
274	        let (rpc, converter, queue, interner) = (rpc.clone(), converter.clone(), queue.clone(), interner.clone());
275	        tasks.spawn(async move {
276	            let mut answered = (SemanticOutcome::default(), Vec::new());
277	            loop {
278	                let next = queue.lock().unwrap_or_else(std::sync::PoisonError::into_inner).pop_front();
279	                let Some(targets) = next else { return Ok(answered) };
280	                let (mut outcome, mut generic) = answer_file(&rpc, &converter, &interner, targets).await?;
281	                answered.0.components.append(&mut outcome.components);
282	                answered.0.fallbacks.append(&mut outcome.fallbacks);
283	                answered.1.append(&mut generic);
284	            }
285	        });
286	    }
287	
288	    let mut outcome = SemanticOutcome::default();
289	    let mut generic = Vec::new();
290	    let mut failure = None;
291	    while let Some(joined) = tasks.join_next().await {
292	        match joined {
293	            Ok(Ok((mut answered, mut instantiations))) => {
294	                outcome.components.append(&mut answered.components);
295	                outcome.fallbacks.append(&mut answered.fallbacks);
296	                generic.append(&mut instantiations);
297	            }
298	            Ok(Err(error)) => {
299	                failure = Some(error);
300	                tasks.abort_all();
301	            }
302	            // A panic inside a worker must not silently leave its components structural.
303	            Err(joined) if joined.is_panic() => {
304	                failure = Some(CallError::Fatal("a worker panicked".to_string()));
305	                tasks.abort_all();
306	            }
307	            // A cancelled task is one this loop aborted after a failure.
308	            Err(_cancelled) => {}
309	        }
310	    }
311	    if let Some(error) = failure {
312	        return Err(error);
313	    }
314	    if !generic.is_empty() {
315	        let mut instantiated =
316	            instantiate::answer(rpc, files, &request.project_root, &interner, request.reverse_queries, generic).await?;
317	        outcome.components.append(&mut instantiated.components);
318	        outcome.fallbacks.append(&mut instantiated.fallbacks);
319	    }
320	
321	    if let (Some(path), Some(recording)) = (&request.record_to, rpc.recording())
322	        && let Ok(json) = serde_json::to_string_pretty(&recording)
323	        && let Err(error) = std::fs::write(path, json)
324	    {
325	        tracing::warn!("could not write the recording to {path}: {error}");
326	    }
327	    tracing::debug!(
328	        requests = ?rpc.calls(),
329	        files = files.len(),
330	        type_memo = ?converters.iter().map(Converter::memo_stats).fold((0, 0), |sum, (hits, misses)| (sum.0 + hits, sum.1 + misses)),
331	        total_ms = started.elapsed().as_millis() as u64,
332	        "semantic backend finished"
333	    );
334	    outcome.components.sort_by(|a, b| a.key.cmp(&b.key));
335	    outcome.fallbacks.sort_by(|a, b| a.key.cmp(&b.key));
336	    Ok(outcome)
337	}
338	
339	fn fallback_of(target: &Target, reason: &str) -> SemanticFallback {
340	    SemanticFallback { key: target.key.clone(), reason: reason.to_string() }
341	}
342	
343	/// A fatal error aborts the run; a call the checker rejected only sends that component to its structural result. The
344	/// generic components come back apart, to be answered from their instantiations once every file is done.
345	async fn answer_file(
346	    rpc: &Rpc,
347	    converter: &Converter,
348	    interner: &PropInterner,
349	    targets: Vec<Target>,
350	) -> Result<(SemanticOutcome, Vec<(Target, Instantiation)>), CallError> {
351	    let mut outcome = SemanticOutcome::default();
352	    let mut generic = Vec::new();
353	    let Some(first) = targets.first() else { return Ok((outcome, generic)) };
354	    let module = match module_exports(rpc, first.file_path.as_str()).await {
355	        Ok(Some(module)) => module,
356	        Ok(None) | Err(CallError::Rejected(_)) => {
357	            outcome
358	                .fallbacks
359	                .extend(targets.iter().map(|target| fallback_of(target, "not part of the checker's program")));
360	            return Ok((outcome, generic));
361	        }
362	        Err(fatal) => return Err(fatal),
363	    };
364	
365	    for target in &targets {
366	        let requests = Arc::new(AtomicU64::new(0));
367	        let started = std::time::Instant::now();
368	        let answered =
369	            REQUESTS.scope(requests.clone(), component::props_of(rpc, converter, interner, &module, target)).await;
370	        tracing::debug!(
371	            component = %target.display_name,
372	            requests = requests.load(Ordering::Relaxed),
373	            ms = started.elapsed().as_millis() as u64,
374	            "semantic component answered"
375	        );
376	        match answered {
377	            Ok(Answer::Props(component::Props { props, composes })) => {
378	                outcome.components.push(SemanticComponent { key: target.key.clone(), props, composes });
379	            }
380	            Ok(Answer::Fallback(reason)) => outcome.fallbacks.push(fallback_of(target, &reason)),
381	            Ok(Answer::Instantiate(instantiation)) => generic.push((target.clone(), instantiation)),
382	            Err(CallError::Rejected(message)) => {
383	                outcome.fallbacks.push(fallback_of(target, &format!("the checker rejected a request: {message}")));
384	            }
385	            Err(fatal) => return Err(fatal),
386	        }
387	    }
388	    Ok((outcome, generic))
389	}
390	
391	/// The module `file` is, as the checker reads it, with its exports; `None` when the file is not in its program.
392	async fn module_exports(rpc: &Rpc, file: &str) -> Result<Option<component::Module>, CallError> {
393	    let Some(symbol) = rpc.source_file_symbol(file).await? else { return Ok(None) };
394	    let exports = rpc.exports_of_module(&symbol.reference).await?;
395	    Ok(Some(component::Module { symbol, exports }))
396	}
397	
398	#[cfg(test)]
399	mod tests {
400	    #![allow(clippy::unwrap_used)]
401	
402	    use caliper_docgen_core::pipeline::{PipelineOptions, extract};
403	
404	    use super::*;
405	
406	    /// A project of `files` components over shared types (a union, an interface base, an `Omit` in an intersection, a
407	    /// recursive alias) whose props all extend an interface the last file augments (`declare global`).
408	    fn shared_types_project(files: usize) -> (tempfile::TempDir, Utf8PathBuf) {
409	        let dir = tempfile::Builder::new().prefix("Programs").tempdir().unwrap();
410	        let root = Utf8PathBuf::from_path_buf(std::fs::canonicalize(dir.path()).unwrap()).unwrap();
411	        std::fs::write(
412	            root.join("types.ts"),
413	            "export type Size = 'sm' | 'md' | 'lg';\n\
414	             export interface Base {\n  /** The id. */\n  id: string;\n  size?: Size;\n}\n\
415	             export type Tree = { label: string; children?: Tree[] };\n\
416	             export type Styled = Omit<Base, 'id'> & { tone?: 'a' | 'b'; onPick?: (value: Size) => void };\n\
417	             declare global { interface Augmented { fromTypes?: number } }\n",
418	        )
419	        .unwrap();
420	        for index in 0..files {
421	            let augments = if index + 1 == files {
422	                "declare global { interface Augmented { fromLastFile?: boolean } }\n"
423	            } else {
424	                ""
425	            };
426	            std::fs::write(
427	                root.join(format!("C{index}.tsx")),
428	                format!(
429	                    "import type {{ Base, Styled, Tree }} from './types';\n{augments}\
430	                     export interface C{index}Props extends Base, Augmented {{ own{index}: number; tree?: Tree; styled: Styled }}\n\
431	                     export function C{index}(props: C{index}Props) {{ return null; }}\n"
432	                ),
433	            )
434	            .unwrap();
435	        }
436	        (dir, root)
437	    }
438	
439	    fn answered(root: &Utf8Path, programs: usize) -> SemanticOutcome {
440	        let output = extract(&PipelineOptions { src_dirs: vec![root.to_owned()], ..PipelineOptions::default() });
441	        let request = SemanticRequest::new(root.to_owned(), targets_of(&output));
442	        let runtime = tokio::runtime::Builder::new_multi_thread().worker_threads(2).enable_all().build().unwrap();
443	        runtime.block_on(run(request, Some(programs)))
444	    }
445	
446	    /// Three programs on the built-in checker, each answering some of the files, give the answer one program gives:
447	    /// each holds every root file, so what one file declares (here a global augmentation in the last) reaches the
448	    /// components the other programs answer.
449	    #[test]
450	    fn several_programs_answer_as_one_does() {
451	        let (_dir, root) = shared_types_project(9);
452	
453	        let one = answered(&root, 1);
454	        let three = answered(&root, 3);
455	
456	        assert!(one.diagnostics.is_empty() && one.fallbacks.is_empty(), "{one:?}");
457	        assert_eq!(one.components.len(), 9);
458	        for component in &one.components {
459	            let names: Vec<&str> = component.props.iter().map(|prop| prop.name.as_str()).collect();
460	            assert!(names.contains(&"fromLastFile") && names.contains(&"fromTypes"), "{names:?}");
461	        }
462	        assert_eq!(one, three);
463	    }
464	
465	    /// A prop the converter keeps for later components is kept by what makes it, including which of its JSDoc was
466	    /// asked: a component whose structural pass already described `id` is not handed the description another asked for,
467	    /// and the one after it is not handed an empty one. The three are in one file, so they are answered in turn and the
468	    /// later ones find the first one's props kept.
469	    #[test]
470	    fn a_kept_prop_is_one_made_by_the_same_question() {
471	        let (_dir, root) = shared_types_project(0);
472	        let component = |name: &str| {
473	            format!(
474	                "export interface {name}Props extends Base {{ own: number }}\nexport function {name}(props: {name}Props) {{ return null; }}\n"
475	            )
476	        };
477	        let text = format!(
478	            "import type {{ Base }} from './types';\n{}{}{}",
479	            component("C0"),
480	            component("C1"),
481	            component("C2")
482	        );
483	        std::fs::write(root.join("All.tsx"), text).unwrap();
484	        let output = extract(&PipelineOptions { src_dirs: vec![root.clone()], ..PipelineOptions::default() });
485	        let mut targets = targets_of(&output);
486	        for target in &mut targets {
487	            target.described.clear();
488	        }
489	        if let Some(target) = targets.iter_mut().find(|target| target.key == "C1") {
490	            target.described.insert("id".to_string());
491	        }
492	        let runtime = tokio::runtime::Builder::new_multi_thread().worker_threads(2).enable_all().build().unwrap();
493	
494	        let outcome = runtime.block_on(run(SemanticRequest::new(root.clone(), targets), Some(1)));
495	
496	        let description = |key: &str| {
497	            let component = outcome.components.iter().find(|component| component.key == key).unwrap();
498	            component.props.iter().find(|prop| prop.name == "id").unwrap().description.clone()
499	        };
500	        assert_eq!(
501	            (description("C0"), description("C1"), description("C2")),
502	            ("The id.".into(), String::new(), "The id.".into())
503	        );
504	    }
505	}
