40	/// A module as the checker reads it: its own symbol, whose declaration names its file in the checker's spelling, and
41	/// its exports.
42	pub(crate) struct Module {
43	    pub(crate) symbol: SymbolInfo,
44	    pub(crate) exports: Vec<SymbolInfo>,
45	}
46	
47	impl Module {
48	    /// Whether one of `symbol`'s declarations is in this module's file.
49	    fn declares(&self, symbol: &SymbolInfo) -> bool {
50	        let files: Vec<&str> = self.symbol.declarations.iter().map(|declaration| declared_in(declaration)).collect();
51	        symbol.declarations.iter().any(|declaration| files.contains(&declared_in(declaration)))
52	    }
53	}
